-- =====================================================================
-- 병원 약제 업무 표준 용어 예시 데이터 (도메인 10개 / 용어 5000개)
-- ---------------------------------------------------------------------
-- pharmacy_word_seed.sql의 단어로 "주제 단어 + (수식어) + 분류어" 용어를 만든다.
--   예) 처방취소 + 일시 → 처방취소일시,  불출요청 + 처리자 + 아이디 → 불출요청처리자아이디,
--       반납사유 + 코드 → 반납사유코드,  냉장고 + 온도 → 냉장고온도,  아목시실린 + 코드 → 아목시실린코드
-- 주제 단어 이름 끝말로 성격(사람·수량·문서·사유·코드성·장소 등)을 나눠 어울리는 분류어만 붙였다.
-- 업무 규칙(마지막 단어 분류어, 도메인 분류어 일치, 이름·약어 유일, 용어 200자·약어 64자)을 지킨다.
-- 개발·시연용 샘플이며 업무 표준이 아니다.
--
-- 도메인별 용어 건수:
--   코드V20: 1995
--   여부C1: 871
--   번호V20: 649
--   일시DT: 644
--   명V100: 557
--   일자D: 102
--   내용V4000: 78
--   아이디V50: 47
--   횟수I: 34
--   순번I: 12
--   온도N4_1: 6
--   금액N18: 5
--
-- Flyway 마이그레이션이 아니다. 자동 실행되지 않는다.
--
-- 넣는 방법 (로컬 MySQL, Git Bash):
--   docker exec -i dictionary-mysql sh -c 'mysql -uroot -p"$MYSQL_ROOT_PASSWORD" --default-character-set=utf8mb4 dictionary' \
--     < src/main/resources/db/seed/pharmacy_term_seed.sql
--
-- 주의:
--   - standard_term_seed.sql → pharmacy_word_seed.sql 다음에 한 번만 실행한다.
--     같은 이름·약어가 있으면 유일 제약에 걸려 트랜잭션 전체가 실패한다(일부만 들어가지 않는다).
--   - 약제 분류어(일수·횟수·시각·체중·신장·온도·습도·나이·점수·연도)의 도메인도 여기서 만든다.
--   - SQL로 직접 넣으므로 변경 이력(change_history)은 남지 않는다.
-- =====================================================================

START TRANSACTION;

-- 1) 약제 분류어 도메인
INSERT INTO std_domain (name, classifier_word_id, data_type, data_length, data_scale, description, created_at, updated_at)
SELECT '일수I', id, 'INTEGER', NULL, NULL, '일 단위 기간', NOW(6), NOW(6) FROM std_word WHERE name = '일수'
UNION ALL SELECT '횟수I', id, 'INTEGER', NULL, NULL, '회 단위 횟수', NOW(6), NOW(6) FROM std_word WHERE name = '횟수'
UNION ALL SELECT '시각C4', id, 'CHAR', 4, NULL, 'HHmm', NOW(6), NOW(6) FROM std_word WHERE name = '시각'
UNION ALL SELECT '체중N5_2', id, 'DECIMAL', 5, 2, 'kg, 소수 둘째 자리', NOW(6), NOW(6) FROM std_word WHERE name = '체중'
UNION ALL SELECT '신장N5_1', id, 'DECIMAL', 5, 1, 'cm, 소수 첫째 자리', NOW(6), NOW(6) FROM std_word WHERE name = '신장'
UNION ALL SELECT '온도N4_1', id, 'DECIMAL', 4, 1, '섭씨, 소수 첫째 자리', NOW(6), NOW(6) FROM std_word WHERE name = '온도'
UNION ALL SELECT '습도N4_1', id, 'DECIMAL', 4, 1, '%, 소수 첫째 자리', NOW(6), NOW(6) FROM std_word WHERE name = '습도'
UNION ALL SELECT '나이I', id, 'INTEGER', NULL, NULL, '만 나이', NOW(6), NOW(6) FROM std_word WHERE name = '나이'
UNION ALL SELECT '점수N5_2', id, 'DECIMAL', 5, 2, '평가 점수', NOW(6), NOW(6) FROM std_word WHERE name = '점수'
UNION ALL SELECT '연도C4', id, 'CHAR', 4, NULL, 'yyyy', NOW(6), NOW(6) FROM std_word WHERE name = '연도';

-- 2) 표준 용어 5000건과 구성 단어
CREATE TEMPORARY TABLE tmp_seed_term (name VARCHAR(200), abbreviation VARCHAR(64), domain_name VARCHAR(100), description VARCHAR(1000));
CREATE TEMPORARY TABLE tmp_seed_term_word (term_abbreviation VARCHAR(64), seq INT, word_abbreviation VARCHAR(50));

